1	package posemap
2	
3	import (
4		"errors"
5		"fmt"
6		"math"
7		"sort"
8		"sync"
9	)
10	
11	// Map 是一份带持久化文件的二维轨迹与路标地图。零值不可用，须经 Create
12	// 或 Open 得到。单个 Map 可被多个 goroutine 并发使用。
13	type Map struct {
14		mu     sync.Mutex
15		path   string
16		state  *mapState
17		closed bool
18	}
19	
20	// mapState 是地图的全部内存状态。
21	type mapState struct {
22		config       Config
23		trajectory   []Pose // 按时间严格递增；trajectory[0] 为初始位姿
24		landmarks    map[string]*landmarkState
25		segments     map[string]*segmentRecord
26		sources      []*frameSource // sources[k] 对应 trajectory[k+1]；长度恒为 len(trajectory)-1
27		corrections  []*CorrectionRecord
28		corrIndex    map[string]string              // 校正标识 -> 首次内容指纹
29		invalRecords []*invalidationRecord          // 按提交次序的成功失效操作
30		invalIndex   map[string]*invalidationRecord // 失效标识 -> 首次记录
31	}
32	
33	// frameSource 是生成某一帧的原始输入，供回环校正重放路标观测与累计
34	// 原运动方差。该切片中的 nil 元素表示对应帧来自不携带逐帧依据的旧
35	// 文件，涉及它的历史范围不能校正。
36	type frameSource struct {
37		moveVariance float64
38		observations []Observation
39	}
40	
41	// landmarkState 是同一标识历次出现的聚合状态。appearances 按出现编号
42	// 递增保存（编号即下标+1）；最后一次出现可能仍为当前有效记录，也可能
43	// 已被失效。失效后的旧出现不参与新观测的合并；下一次出现从编号 1 起的
44	// 全新记录开始，观测计数从 1 计起。
45	//
46	// legacy* 只用于打开不携带逐帧观测来源的旧文件：旧文件中每一帧的观测
47	// 无法重放，因此旧文件第 1 次出现的全部观测贡献视为固定的 legacyCount
48	// 次平均，不随后续校正改变；旧文件之后新导入且依据完整的观测再做增量
49	// 平均。由本版本创建/导入的出现 legacyCount 为 0，全部观测均可重放。
50	type landmarkState struct {
51		appearances []*occurrenceState
52	}
53	
54	// occurrenceState 是某一标识某一次出现的状态。
55	type occurrenceState struct {
56		x             float64
57		y             float64
58		count         int
59		legacyCount   int
60		legacyMX      float64
61		legacyMY      float64
62		firstSeenTime int64 // 首次观测所在帧时间
63		hasFirstSeen  bool  // 旧文件缺少来源时为假
64		active        bool  // 是否为当前有效记录
65		invalidTime   int64 // 失效时间（提交时当前位姿时间）
66		invalidReason string
67		invalidOpID   string
68	}
69	
70	// activeOccurrence 返回当前有效记录；不存在（从未出现或最近一次已失效）
71	// 时返回 nil。
72	func (lm *landmarkState) activeOccurrence() *occurrenceState {
73		if len(lm.appearances) == 0 {
74			return nil
75		}
76		last := lm.appearances[len(lm.appearances)-1]
77		if !last.active {
78			return nil
79		}
80		return last
81	}
82	
83	// invalidationRecord 记录一次成功失效操作的首次内容与结果，供相同操作
84	// 标识以相同原因、相同路标集合重复提交时直接返回。
85	type invalidationRecord struct {
86		id     string
87		reason string
88		hash   string // 路标集合（排序后）的指纹
89		result InvalidationResult
90	}
91	
92	// segmentRecord 记录一个已成功保存的段：内容指纹与首次导入结果，
93	// 供相同内容重复导入时直接返回。
94	type segmentRecord struct {
95		hash   string
96		result ImportResult
97	}
98	
99	// ImportResult 是一次成功段导入的结果：本段末位姿及方差，以及本段
100	// 涉及（观测到）的全部路标标识（去重、按标识排序）。
101	type ImportResult struct {
102		EndPose     Pose
103		LandmarkIDs []string
104	}
105	
106	// Create 在 path 处创建一份新地图并写入初始文件。path 已存在时返回
107	// 错误，以免覆盖既有数据（既有地图请用 Open）。
108	func Create(path string, cfg Config) (*Map, error) {
109		if err := validateConfig(cfg); err != nil {
110			return nil, err
111		}
112		st := &mapState{
113			config:       cfg,
114			trajectory:   []Pose{{Time: cfg.InitialTime, X: cfg.InitialX, Y: cfg.InitialY, Heading: cfg.InitialHeading, Variance: cfg.InitialVariance}},
115			landmarks:    make(map[string]*landmarkState),
116			segments:     make(map[string]*segmentRecord),
117			corrIndex:    make(map[string]string),
118			invalRecords: nil,
119			invalIndex:   make(map[string]*invalidationRecord),
120		}
121		m := &Map{path: path, state: st}
122		// O_EXCL：目标已存在即失败，绝不当作新地图覆盖。
123		if err := m.saveExclusive(); err != nil {
124			return nil, err
125		}
126		return m, nil
127	}
128	
129	// Open 打开 path 处由 Create/导入生成的地图文件。文件不存在时返回
130	// 包装了 fs.ErrNotExist 的错误；文件损坏返回可 errors.Is(ErrCorrupt)
131	// 的错误；格式版本不支持返回 ErrUnsupportedVersion。Open 绝不覆盖
132	// 无法识别的文件。
133	func Open(path string) (*Map, error) {
134		st, err := loadFile(path)
135		if err != nil {
136			return nil, err
137		}
138		return &Map{path: path, state: st}, nil
139	}
140	
141	// Path 返回地图对应的本地数据文件路径。
142	func (m *Map) Path() string {
143		m.mu.Lock()
144		defer m.mu.Unlock()
145		return m.path
146	}
147	
148	// Close 关闭地图。每次成功导入都已落盘，Close 本身不修改数据文件；
149	// 关闭后再调用其他方法返回 ErrClosed。
150	func (m *Map) Close() error {
151		m.mu.Lock()
152		defer m.mu.Unlock()
153		m.closed = true
154		return nil
155	}
156	
157	func validateConfig(cfg Config) error {
158		switch {
159		case !isFinite(cfg.InitialX) || !isFinite(cfg.InitialY) || !isFinite(cfg.InitialHeading):
160			return fmt.Errorf("%w: non-finite initial pose", ErrInvalidConfig)
161		case !isFinite(cfg.InitialVariance) || cfg.InitialVariance < 0:
162			return fmt.Errorf("%w: initial variance must be non-negative and finite", ErrInvalidConfig)
163		case cfg.MaxInterval <= 0:
164			return fmt.Errorf("%w: max interval must be positive", ErrInvalidConfig)
165		case !isFinite(cfg.MergeDistance) || cfg.MergeDistance <= 0:
166			return fmt.Errorf("%w: merge distance must be positive and finite", ErrInvalidConfig)
167		default:
168			return nil
169		}
170	}
171	
172	// ImportSegment 导入一批带非空段标识的有序帧。
173	//
174	// 整段要么全部生效（含落盘），要么因可区分的 *RejectError 被整段拒绝，
175	// 此前已提交的位姿、路标、观测次数不受影响。输入本身全为有限数值并不保证
176	// 推演结果有限：运动完成后的位置、朝向、累计位置方差，或某条观测转换到
177	// 地图坐标后的位置若出现 NaN/无穷值，仍以 RejectNonFinite 拒绝产生异常
178	// 的帧（从零开始的帧序号；路标坐标异常时携带路标标识），不会留到保存时
179	// 才以普通编码错误失败。已成功保存的段标识再次以
180	// 相同内容导入时，直接返回首次导入的结果且不改变当前数据；同一标识
181	// 对应不同内容则以 RejectDuplicateMismatch 拒绝。
182	func (m *Map) ImportSegment(seg Segment) (ImportResult, error) {
183		m.mu.Lock()
184		defer m.mu.Unlock()
185		if m.closed {
186			return ImportResult{}, ErrClosed
187		}
188		st := m.state
189	
190		if seg.ID == "" {
191			return ImportResult{}, &RejectError{Kind: RejectEmptyID}
192		}
193		if len(seg.Frames) == 0 {
194			return ImportResult{}, &RejectError{Kind: RejectEmptySegment}
195		}
196	
197		// 已保存段：相同内容直接返回首次结果；不同内容明确拒绝。
198		// 不做任何校验或状态变更，即使其后又导入过其他段。
199		if rec, ok := st.segments[seg.ID]; ok {
200			if canonicalHash(seg.Frames) == rec.hash {
201				return cloneResult(rec.result), nil
202			}
203			return ImportResult{}, &RejectError{Kind: RejectDuplicateMismatch, Landmark: seg.ID, HasLandmark: true}
204		}
205	
206		// ---- 在暂存区上校验并推演，真实状态此时保持不变 ----
207		cur := st.trajectory[len(st.trajectory)-1]
208		prevTime := cur.Time
209		newPoses := make([]Pose, 0, len(seg.Frames))
210		// staged 记录本帧触及路标的暂存“当前出现”副本：created 为真表示这是
211		// 本段内首次新观测产生的新出现（此前不存在当前有效记录）。
212		type stagedLM struct {
213			occ     *occurrenceState
214			created bool
215		}
216		staged := make(map[string]stagedLM) // 本段触及路标的暂存聚合
217		touched := make(map[string]struct{})
218	
219		reject := func(kind string, frame int) (ImportResult, error) {
220			return ImportResult{}, &RejectError{Kind: kind, Frame: frame, HasFrame: true}
221		}
222	
223		for i, f := range seg.Frames {
224			// 时间：严格递增；首帧必须晚于初始时间或上一段末帧。
225			if f.Time <= prevTime {
226				return reject(RejectTimeOrder, i)
227			}
228			// 相邻位姿间隔上限。
229			if f.Time-prevTime > m.state.config.MaxInterval {
230				return reject(RejectInterval, i)
231			}
232			// 运动数值有限、方差非负。
233			if !isFinite(f.DX) || !isFinite(f.DY) || !isFinite(f.DHeading) || !isFinite(f.MoveVariance) {
234				return reject(RejectNonFinite, i)
235			}
236			if f.MoveVariance < 0 {
237				return reject(RejectNegativeVariance, i)
238			}
239			// 观测标识非空、观测位置有限。
240			for _, ob := range f.Observations {
241				if ob.ID == "" {
242					return reject(RejectEmptyID, i)
243				}
244				if !isFinite(ob.X) || !isFinite(ob.Y) {
245					return ImportResult{}, &RejectError{Kind: RejectNonFinite, Frame: i, HasFrame: true, Landmark: ob.ID, HasLandmark: true}
246				}
247			}
248	
249			// 运动：先按运动前朝向把平移转换到地图坐标，再更新朝向并归一。
250			nx, ny := localToMap(cur.X, cur.Y, cur.Heading, f.DX, f.DY)
251			cur = Pose{
252				Time:     f.Time,
253				X:        nx,
254				Y:        ny,
255				Heading:  normalizeAngle(cur.Heading + f.DHeading),
256				Variance: cur.Variance + f.MoveVariance,
257			}
258			// 输入本身有限并不保证结果有限：位置叠加、朝向累计或方差累计
259			// 仍可能溢出为无穷（例如 1e308 再前进 1e308）。按数值异常拒绝
260			// 产生异常的这一帧，而不是等到保存时得到普通编码错误。
261			if !isFinite(cur.X) || !isFinite(cur.Y) || !isFinite(cur.Heading) || !isFinite(cur.Variance) {
262				return reject(RejectNonFinite, i)
263			}
264			newPoses = append(newPoses, cur)
265	
266			// 观测按运动完成后的位姿转换到地图坐标，同帧按输入次序处理。
267			for _, ob := range f.Observations {
268				mx, my := localToMap(cur.X, cur.Y, cur.Heading, ob.X, ob.Y)
269				// 转换结果可能因位姿/观测坐标过大而溢出：无论该路标是首次
270				// 出现、失效后再次出现，还是与有效记录合并，数值异常都优先
271				// 于距离冲突，按同一原因拒绝并携带路标标识。
272				if !isFinite(mx) || !isFinite(my) {
273					return ImportResult{}, &RejectError{Kind: RejectNonFinite, Frame: i, HasFrame: true, Landmark: ob.ID, HasLandmark: true}
274				}
275				s, seen := staged[ob.ID]
276				if !seen {
277					if lm := st.landmarks[ob.ID]; lm != nil {
278						if active := lm.activeOccurrence(); active != nil {
279							// 复制当前有效出现，避免提前修改真实状态。旧出现
280							// （已失效）永不参与新观测的合并。
281							cp := *active
282							s = stagedLM{occ: &cp, created: false}
283						}
284					}
285					if s.occ == nil {
286						// 从未出现或最近一次已失效：本次为新的一次出现，
287						// 编号在提交时确定，观测计数从 1 开始。
288						s = stagedLM{
289							occ: &occurrenceState{
290								x: mx, y: my, count: 1,
291								firstSeenTime: f.Time, hasFirstSeen: true,
292								active: true,
293							},
294							created: true,
295						}
296						staged[ob.ID] = s
297						touched[ob.ID] = struct{}{}
298						continue
299					}
300					staged[ob.ID] = s
301				}
302				occ := s.occ
303				if math.Hypot(mx-occ.x, my-occ.y) > m.state.config.MergeDistance {
304					return ImportResult{}, &RejectError{Kind: RejectLandmarkConflict, Frame: i, HasFrame: true, Landmark: ob.ID, HasLandmark: true}
305				}
306				occ.x = mergeMean(occ.x, mx, occ.count)
307				occ.y = mergeMean(occ.y, my, occ.count)
308				occ.count++
309				touched[ob.ID] = struct{}{}
310			}
311	
312			prevTime = f.Time
313		}
314	
315		ids := make([]string, 0, len(touched))
316		for id := range touched {
317			ids = append(ids, id)
318		}
319		sort.Strings(ids)
320		res := ImportResult{EndPose: cur, LandmarkIDs: ids}
321	
322		// 逐帧依据（原运动方差与原始观测）与位姿一一对应，供以后的回环
323		// 校正重放。
324		newSources := make([]*frameSource, len(seg.Frames))
325		for i, f := range seg.Frames {
326			obs := append([]Observation(nil), f.Observations...)
327			newSources[i] = &frameSource{moveVariance: f.MoveVariance, observations: obs}
328		}
329	
330		// ---- 全部校验通过：提交内存状态并落盘；落盘失败精确回滚 ----
331		trajLenBefore := len(st.trajectory)
332		srcLenBefore := len(st.sources)
333		type undoLandmark struct {
334			lm       *landmarkState
335			ok       bool
336			created  bool
337			replaced *occurrenceState // 非新建时被暂存副本替换掉的原当前出现
338		}
339		undo := make(map[string]undoLandmark, len(staged))
340		for id, s := range staged {
341			old, ok := st.landmarks[id]
342			if s.created {
343				// 新的一次出现：可能是该标识的首次出现，也可能接在已失效的
344				// 历次出现之后。编号即追加后的切片长度。
345				lm := old
346				if lm == nil {
347					lm = &landmarkState{}
348				}
349				lm.appearances = append(lm.appearances, s.occ)
350				st.landmarks[id] = lm
351				undo[id] = undoLandmark{lm: old, ok: ok, created: true}
352			} else {
353				// 更新既有当前有效出现（暂存副本替换原指针，旧出现原样保留）。
354				replaced := old.appearances[len(old.appearances)-1]
355				old.appearances[len(old.appearances)-1] = s.occ
356				undo[id] = undoLandmark{lm: old, ok: ok, created: false, replaced: replaced}
357			}
358		}
359		st.trajectory = append(st.trajectory, newPoses...)
360		st.sources = append(st.sources, newSources...)
361		st.segments[seg.ID] = &segmentRecord{hash: canonicalHash(seg.Frames), result: cloneResult(res)}
362	
363		if err := m.saveReplace(); err != nil {
364			st.trajectory = st.trajectory[:trajLenBefore]
365			st.sources = st.sources[:srcLenBefore]
366			for id, u := range undo {
367				switch {
368				case !u.ok:
369					delete(st.landmarks, id)
370				case u.created:
371					u.lm.appearances = u.lm.appearances[:len(u.lm.appearances)-1]
372				default:
373					u.lm.appearances[len(u.lm.appearances)-1] = u.replaced
374				}
375			}
376			delete(st.segments, seg.ID)
377			return ImportResult{}, err
378		}
379		return res, nil
380	}
381	
382	func cloneResult(r ImportResult) ImportResult {
383		ids := make([]string, len(r.LandmarkIDs))
384		copy(ids, r.LandmarkIDs)
385		r.LandmarkIDs = ids
386		return r
387	}
388	
389	// CurrentPose 返回当前位姿及其位置方差；尚无帧导入时返回初始位姿。
390	func (m *Map) CurrentPose() (Pose, error) {
391		m.mu.Lock()
392		defer m.mu.Unlock()
393		if m.closed {
394			return Pose{}, ErrClosed
395		}
396		return m.state.trajectory[len(m.state.trajectory)-1], nil
397	}
398	
399	// PoseAt 返回不晚于 t 的最后一份历史位姿及其方差。t 早于初始时间时
400	// 返回 ErrNotFound。
401	func (m *Map) PoseAt(t int64) (Pose, error) {
402		m.mu.Lock()
403		defer m.mu.Unlock()
404		if m.closed {
405			return Pose{}, ErrClosed
406		}
407		tr := m.state.trajectory
408		// j 为第一个时间 > t 的位置。
409		j := sort.Search(len(tr), func(j int) bool { return tr[j].Time > t })
410		if j == 0 {
411			return Pose{}, ErrNotFound
412		}
413		return tr[j-1], nil
414	}
415	
416	// Rect 描述一个包含边界的轴对齐矩形查询区域，单位米。
417	type Rect struct {
418		MinX, MinY, MaxX, MaxY float64
419	}
420	
421	// LandmarksInRect 返回矩形（含边界）内当前仍有效路标的最新一次出现及
422	// 观测次数，按标识排序；已失效（且尚未再次出现）的路标立即排除，区域为
423	// 空时返回非 nil 的空切片。上下界颠倒或含非有限值时报 ErrInvalidRect。
424	func (m *Map) LandmarksInRect(r Rect) ([]Landmark, error) {
425		m.mu.Lock()
426		defer m.mu.Unlock()
427		if m.closed {
428			return nil, ErrClosed
429		}
430		if !isFinite(r.MinX) || !isFinite(r.MinY) || !isFinite(r.MaxX) || !isFinite(r.MaxY) ||
431			r.MinX > r.MaxX || r.MinY > r.MaxY {
432			return nil, fmt.Errorf("%w: min bounds must not exceed max bounds and all values must be finite", ErrInvalidRect)
433		}
434		var out []Landmark
435		for id, lm := range m.state.landmarks {
436			occ := lm.activeOccurrence()
437			if occ == nil {
438				continue // 最近一次出现已失效：立即排除。
439			}
440			if occ.x >= r.MinX && occ.x <= r.MaxX && occ.y >= r.MinY && occ.y <= r.MaxY {
441				out = append(out, Landmark{ID: id, X: occ.x, Y: occ.y, Count: occ.count})
442			}
443		}
444		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
445		if out == nil {
446			out = []Landmark{}
447		}
448		return out, nil
449	}
450	
451	// AsRejectError 返回错误对应的 *RejectError；不是段拒绝错误时返回 nil、false。
452	func AsRejectError(err error) (*RejectError, bool) {
453		var r *RejectError
454		if errors.As(err, &r) {
455			return r, true
456		}
457		return nil, false
458	}
459

